import React from 'react';
import { useUIStore } from '../../store/useAppStore';
import { useIncomeStore } from '../../store/useIncomeStore';
import { useExpenseStore } from '../../store/useExpenseStore';
import { getSourceEmoji } from '../../lib/income-sources';
import { cn } from '../../lib/utils';
import { useRandomGlows } from '../../hooks/useRandomGlows';
import { getTablerIconByEmoji } from '../../lib/icons-map';

interface IncomeSummaryCardProps {
  activeFilter?: { type: 'FIAT' | 'CRYPTO_SOURCE'; value: string } | null;
  onToggleFilter?: (filter: { type: 'FIAT' | 'CRYPTO_SOURCE'; value: string } | null) => void;
}

export const IncomeSummaryCard = React.memo(({ activeFilter, onToggleFilter }: IncomeSummaryCardProps) => {
  const { incomes } = useIncomeStore();
  const { activeYear: year, activeMonth: month } = useUIStore();
  const { currency } = useExpenseStore();
  const glows = useRandomGlows('summary');

  const monthPrefix = `${year}-${String(month).padStart(2, '0')}`;
  const monthIncomes = incomes.filter((i) => i.date.startsWith(monthPrefix));

  // Combined Monthly Totals
  const totalRevenueUsd = monthIncomes.reduce((sum, i) => {
    const pnlUsd = i.has_cost_basis ? (i.value_usd - (i.cost_value_usd ?? 0)) : i.value_usd;
    return sum + pnlUsd;
  }, 0);

  const totalRevenueIdr = monthIncomes.reduce((sum, i) => {
    const pnlIdr = i.has_cost_basis ? (i.value_idr - (i.cost_value_idr ?? 0)) : i.value_idr;
    return sum + pnlIdr;
  }, 0);

  // Group and combine Fiat + Crypto sources for space-saving Breakdown list
  const gainsList = React.useMemo(() => {
    const list: Array<{
      type: 'FIAT' | 'CRYPTO_SOURCE';
      source: string;
      emoji: string;
      tickersString: string;
      valueUsd: number;
      valueIdr: number;
    }> = [];

    const fiat = monthIncomes.filter((i) => i.asset_type === 'FIAT');
    const crypto = monthIncomes.filter((i) => i.asset_type === 'CRYPTO');

    // 1. Fiat Cash Row
    if (fiat.length > 0) {
      const totalFiatIdr = fiat.reduce((sum, i) => sum + i.value_idr, 0);
      const totalFiatUsd = fiat.reduce((sum, i) => sum + i.value_usd, 0);
      const uniqueFiatCurrencies = Array.from(new Set(fiat.map((i) => i.currency).filter(Boolean)));
      list.push({
        type: 'FIAT',
        source: 'Fiat Cash',
        emoji: '💵',
        tickersString: uniqueFiatCurrencies.join(', ') || 'IDR',
        valueUsd: totalFiatUsd,
        valueIdr: totalFiatIdr,
      });
    }

    // 2. Crypto Sources Rows
    const cryptoGainsMap: Record<string, { source: string; tickers: Set<string>; valueUsd: number; valueIdr: number }> = {};
    crypto.forEach((entry) => {
      const ticker = entry.cost_ticker || entry.ticker || '';
      const key = entry.source_type;
      const pnlUsd = entry.has_cost_basis ? (entry.value_usd - (entry.cost_value_usd ?? 0)) : entry.value_usd;
      const pnlIdr = entry.has_cost_basis ? (entry.value_idr - (entry.cost_value_idr ?? 0)) : entry.value_idr;

      if (!cryptoGainsMap[key]) {
        cryptoGainsMap[key] = {
          source: entry.source_type,
          tickers: new Set<string>(),
          valueUsd: 0,
          valueIdr: 0,
        };
      }
      if (ticker) {
        cryptoGainsMap[key].tickers.add(ticker);
      }
      cryptoGainsMap[key].valueUsd += pnlUsd;
      cryptoGainsMap[key].valueIdr += pnlIdr;
    });

    Object.values(cryptoGainsMap).forEach((cg) => {
      list.push({
        type: 'CRYPTO_SOURCE',
        source: cg.source,
        emoji: getSourceEmoji(cg.source),
        tickersString: Array.from(cg.tickers).join(', '),
        valueUsd: cg.valueUsd,
        valueIdr: cg.valueIdr,
      });
    });

    // Sort by absolute valueIdr descending so the largest items appear first
    return list.sort((a, b) => Math.abs(b.valueIdr) - Math.abs(a.valueIdr));
  }, [monthIncomes]);

  // Dynamic Scroll Indicator State & Ref
  const [scrollState, setScrollState] = React.useState({
    showTopFade: false,
    showBottomFade: false,
  });
  const listRef = React.useRef<HTMLDivElement>(null);

  const updateScrollIndicator = React.useCallback(() => {
    const el = listRef.current;
    if (!el) return;

    const { scrollTop, scrollHeight, clientHeight } = el;
    const canScroll = scrollHeight > clientHeight + 4;

    setScrollState({
      showTopFade: canScroll && scrollTop > 4,
      showBottomFade: canScroll && scrollTop + clientHeight < scrollHeight - 4,
    });
  }, []);

  React.useEffect(() => {
    const rafId = requestAnimationFrame(updateScrollIndicator);
    return () => cancelAnimationFrame(rafId);
  }, [gainsList, updateScrollIndicator]);

  const maskStyle = React.useMemo(() => {
    const { showTopFade, showBottomFade } = scrollState;
    if (showTopFade && showBottomFade) {
      return 'linear-gradient(to bottom, transparent 0%, white 12px, white calc(100% - 12px), transparent 100%)';
    }
    if (showTopFade) {
      return 'linear-gradient(to bottom, transparent 0%, white 12px, white 100%)';
    }
    if (showBottomFade) {
      return 'linear-gradient(to bottom, white 0%, white calc(100% - 12px), transparent 100%)';
    }
    return 'none';
  }, [scrollState]);

  return (
    <div className="relative w-full h-full rounded-3xl border border-transparent bg-gradient-to-br from-[#1A1A1A] via-[#131313] to-[#0E0E0E] pt-5 pb-3 px-5 flex flex-col justify-start text-[#F5F0E8] shadow-[0_12px_30px_rgba(0,0,0,0.25)] overflow-hidden">
      {/* Noise texture overlay to eliminate color banding (dithering) */}
      <div 
        className="absolute inset-0 pointer-events-none opacity-[0.03] mix-blend-overlay z-10"
        style={{
          backgroundImage: `url("data:image/png;base64,")`,
         }}
       />

      {/* Randomised ambient glows */}
      {glows.map((g, i) => (
        <div
          key={i}
          className="absolute pointer-events-none"
          style={{
            top: g.top,
            bottom: g.bottom,
            left: g.left,
            right: g.right,
            width: g.width,
            height: g.height,
            background: g.color,
            opacity: g.opacity,
            borderRadius: g.borderRadius,
            filter: `blur(${g.blur}px)`,
            willChange: 'filter, transform',
            transform: 'translate3d(0,0,0)',
          }}
        />
      ))}
      {/* Top edge shimmer */}
      <div className="absolute top-0 left-6 right-6 h-px bg-gradient-to-r from-transparent via-white/[0.12] to-transparent pointer-events-none" />

      {/* Header Summary */}
      <div className="flex flex-col gap-1 border-b border-white/[0.04] pb-4 shrink-0">
        <div className="flex items-center gap-1.5">
          <p className="text-[10px] font-semibold text-white/30 uppercase tracking-widest">
            Monthly Summary
          </p>
        </div>
        <div className="flex flex-col sm:flex-row sm:items-baseline justify-between gap-2 mt-1">
          <div className="flex items-baseline gap-2">
            <span className="text-3xl font-bold tracking-tight text-white leading-none">
              {currency === 'IDR' 
                ? `Rp ${totalRevenueIdr.toLocaleString('id-ID')}`
                : `$${totalRevenueUsd.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`}
            </span>
            <span className="text-xs text-white/30 font-medium">
              {currency === 'IDR'
                ? `≈ $${totalRevenueUsd.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
                : `≈ Rp ${totalRevenueIdr.toLocaleString('id-ID')}`}
            </span>
          </div>
        </div>
      </div>

      {gainsList.length > 0 ? (
        <div className="flex flex-col gap-2 mt-4 flex-1 min-h-0">
          <p className="text-[9px] font-semibold text-white/30 uppercase tracking-widest pl-1 shrink-0">
            Breakdown
          </p>
          <div 
            ref={listRef}
            onScroll={updateScrollIndicator}
            data-no-drag="true"
            className="flex flex-col rounded-2xl border border-white/[0.06] bg-white/[0.01] overflow-hidden divide-y divide-white/[0.04] max-h-[135px] overflow-y-auto scrollbar-none"
            style={{
              WebkitMaskImage: maskStyle,
              maskImage: maskStyle,
            }}
          >
            {gainsList.map((g, idx) => {
              const isSelected = 
                (g.type === 'FIAT' && activeFilter?.type === 'FIAT') ||
                (g.type === 'CRYPTO_SOURCE' && activeFilter?.type === 'CRYPTO_SOURCE' && activeFilter.value === g.source);
              const isDimmed = activeFilter && !isSelected;
              const isProfit = g.valueUsd >= 0;
              return (
                <button 
                  key={idx} 
                  type="button"
                  onClick={() => {
                    if (!onToggleFilter) return;
                    if (g.type === 'FIAT') {
                      onToggleFilter(isSelected ? null : { type: 'FIAT', value: 'fiat' });
                    } else {
                      onToggleFilter(isSelected ? null : { type: 'CRYPTO_SOURCE', value: g.source });
                    }
                  }}
                  className={cn(
                    "w-full text-left cursor-pointer flex justify-between items-center px-3.5 py-1.5 transition-all duration-200 relative overflow-hidden group shrink-0",
                    isSelected
                      ? "bg-[#B8F55A]/5 text-[#B8F55A] shadow-[inset_0_0_12px_rgba(184,245,90,0.03)]"
                      : "hover:bg-white/[0.02]",
                    isDimmed && "opacity-30 scale-[0.98]"
                  )}
                >
                  <div className="flex items-center gap-2.5 min-w-0">
                    {React.createElement(getTablerIconByEmoji(g.emoji), { size: 18, className: "shrink-0 text-white/40" })}
                    <div className="flex flex-col min-w-0">
                      <span className="font-bold text-white/90 uppercase truncate text-[9px] tracking-wider">
                        {g.source}
                      </span>
                      {g.tickersString && (
                        <span className="text-[9px] text-white/30 truncate mt-0.5">
                          {g.tickersString}
                        </span>
                      )}
                    </div>
                  </div>
                  <div className="text-right font-medium shrink-0">
                    <p className={cn("text-xs font-semibold", isProfit ? "text-white/85" : "text-red-400/75")}>
                      {currency === 'IDR'
                        ? `${g.valueIdr < 0 ? '-' : ''}Rp ${Math.abs(Math.round(g.valueIdr)).toLocaleString('id-ID')}`
                        : `${g.valueUsd < 0 ? '-' : ''}$${Math.abs(g.valueUsd).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`}
                    </p>
                    <p className="text-[9px] text-white/30 mt-0.5">
                      {currency === 'IDR'
                        ? `(${g.valueUsd < 0 ? '-' : ''}$${Math.abs(g.valueUsd).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })})`
                        : `(${g.valueIdr < 0 ? '-' : ''}Rp ${Math.abs(Math.round(g.valueIdr)).toLocaleString('id-ID')})`}
                    </p>
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      ) : (
        <div className="text-center py-6 flex-1 flex items-center justify-center">
          <p className="text-sm font-medium text-white/30 italic">No income logged for this month</p>
        </div>
      )}
    </div>
  );
});
